import type { Metadata } from 'next';

// Generated by src/app/opengraph-image.tsx.
const ogImage = { url: '/opengraph-image', width: 1200, height: 630, alt: 'SyncSphere — websites, WhatsApp and marketing for Ugandan businesses' };

/** Per-page title, description, canonical URL and social preview text. */
export function pageMeta(path: string, title: string, description: string, opts: { noindex?: boolean } = {}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { type: 'website', siteName: 'SyncSphere', locale: 'en_UG', title, description, url: path, images: [ogImage] },
    twitter: { card: 'summary_large_image', title, description, images: [ogImage.url] },
    ...(opts.noindex ? { robots: { index: false, follow: false } } : {}),
  };
}
